import{_ as a,C as r,o as d,c as i,aj as e,E as n}from"./framework.js";const s="/kb-docs/cms/getting-started/%E5%AF%BC%E5%85%A5%E7%AB%99%E7%82%B9.png",l="/kb-docs/cms/getting-started/%E5%85%8B%E9%9A%86%E7%AB%99%E7%82%B9.png",A=JSON.parse('{"title":"新建站点 | Cms / Getting Started | Documentation","description":"新建站点 in Kooboo: ::: tip 前置 请先完成 登录与站点列表。若在某一文件夹内点击 新建站点，创建完成后站点会归入该文件夹。 :::","frontmatter":{"title":"新建站点 | Cms / Getting Started | Documentation","description":"新建站点 in Kooboo: ::: tip 前置 请先完成 登录与站点列表。若在某一文件夹内点击 新建站点，创建完成后站点会归入该文件夹。 :::","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/getting-started/create-site.html"}]]},"headers":[],"relativePath":"zh/cms/getting-started/create-site.md","filePath":"cms/getting-started/create-site.md","lastUpdated":1780283316000}'),c={name:"zh/cms/getting-started/create-site.md"};function g(h,t,m,_,p,b){const o=r("DocImage");return d(),i("div",null,[t[0]||(t[0]=e('<h1 id="新建站点" tabindex="-1">新建站点 <a class="header-anchor" href="#新建站点" aria-label="Permalink to &quot;新建站点&quot;">​</a></h1><blockquote><p>从 <strong>我的站点</strong> 创建站点：空白站点、导入包、克隆现有站点</p></blockquote><div class="tip custom-block"><p class="custom-block-title">前置</p><p>请先完成 <a href="./login-and-site-list.html">登录与站点列表</a>。若在某一文件夹内点击 <strong>新建站点</strong>，创建完成后站点会归入该文件夹。</p></div><h2 id="进入创建向导" tabindex="-1">进入创建向导 <a class="header-anchor" href="#进入创建向导" aria-label="Permalink to &quot;进入创建向导&quot;">​</a></h2><ol><li>在 <strong>我的站点</strong> 首页点击 <strong>新建站点</strong>。</li><li>地址变为 <code>/_Admin/create</code>（若在文件夹内，可能带有 <code>?currentFolder=文件夹名</code>）。</li><li>左侧为当前创建方式表单，右侧为 <strong>切换创建方式</strong> 列表。</li></ol>',5)),n(o,{src:"/cms/getting-started/04-create-site-nav.png",alt:"新建站点：左侧空白站点表单，右侧切换创建方式",width:"1120"}),t[1]||(t[1]=e('<h2 id="创建方式" tabindex="-1">创建方式 <a class="header-anchor" href="#创建方式" aria-label="Permalink to &quot;创建方式&quot;">​</a></h2><p>右侧可切换以下方式（名称以中文界面为准）：</p><table tabindex="0"><thead><tr><th>方式</th><th>路由</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>空白站点</strong></td><td><code>/_Admin/create</code></td><td>从零开始，自定站点名与默认域名</td></tr><tr><td><strong>克隆站点</strong></td><td><code>/_Admin/create/clone</code></td><td>从已有站点或远程地址复制一份</td></tr><tr><td><strong>导入站点</strong></td><td><code>/_Admin/create/import</code></td><td>上传 Kooboo 导出包或标准 HTML 包</td></tr><tr><td><strong>挑选模板</strong></td><td>跳转模板市场</td><td>基于模板创建（本系列暂不逐步说明）</td></tr></tbody></table><h2 id="空白站点" tabindex="-1">空白站点 <a class="header-anchor" href="#空白站点" aria-label="Permalink to &quot;空白站点&quot;">​</a></h2><p>默认即空白站点创建页。</p><ol><li>填写 <strong>站点名称</strong>（后台显示用，需唯一）。</li><li>填写 <strong>域名</strong>：子域名 + 平台提供的根域名（下拉选择）。子域名与站点名称在未手动分别编辑时会联动。</li><li>点击 <strong>开始创建</strong>。</li><li>创建成功后回到 <strong>我的站点</strong> 列表；在对应站点上点击 <strong>管理</strong> 进入站点后台。</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>空白站点不会自动打开站点后台。创建后请从列表进入 <strong>管理</strong>，再开始建页面、内容类型等。</p></div><h2 id="导入站点" tabindex="-1">导入站点 <a class="header-anchor" href="#导入站点" aria-label="Permalink to &quot;导入站点&quot;">​</a></h2><img src="'+s+'" alt="导入站点" class="bordered-image" width="1120"><ol><li>在创建向导右侧选择 <strong>导入站点</strong>，进入 <code>/_Admin/create/import</code>。</li><li>按提示上传 <strong>zip</strong> 包（Kooboo 站点导出包，或标准 HTML 包；后者由系统转换为 Kooboo 站点）。</li><li>完成导入后按界面提示进入列表或站点后台（以实际流程为准）。</li></ol><h2 id="克隆站点" tabindex="-1">克隆站点 <a class="header-anchor" href="#克隆站点" aria-label="Permalink to &quot;克隆站点&quot;">​</a></h2><img src="'+l+'" alt="导入站点" class="bordered-image" width="1120"><ol><li>选择 <strong>克隆站点</strong>，进入 <code>/_Admin/create/clone</code>。</li><li>按表单选择源站点或填写克隆来源（以界面字段为准）。</li><li>确认后生成新站点，出现在 <strong>我的站点</strong> 列表中。</li></ol><h2 id="创建完成后建议顺序" tabindex="-1">创建完成后建议顺序 <a class="header-anchor" href="#创建完成后建议顺序" aria-label="Permalink to &quot;创建完成后建议顺序&quot;">​</a></h2><p>进入站点后台（<code>/_Admin/site?SiteId=...</code>）后，建议：</p><ol><li><a href="./../navigation.html">站点后台菜单总览</a> — 熟悉左侧菜单</li><li><strong>页面</strong>、<strong>媒体库</strong> — 先有可访问页面（相关文档待补充）</li><li><a href="./../content/">内容</a> — 若要用 <code>k.content</code></li><li><a href="/kb-docs/zh/templateEngine/">模板引擎</a> — 开发 Layout / Page / View</li></ol><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>深链</th></tr></thead><tbody><tr><td>我的站点</td><td><code>/_Admin/</code></td></tr><tr><td>新建站点</td><td><code>/_Admin/create</code></td></tr><tr><td>导入</td><td><code>/_Admin/create/import</code></td></tr><tr><td>克隆</td><td><code>/_Admin/create/clone</code></td></tr><tr><td>站点控制面板</td><td><code>/_Admin/site?SiteId={站点GUID}</code></td></tr></tbody></table>',18))])}const k=a(c,[["render",g]]);export{A as __pageData,k as default};
